-- YG-960–968: kişisel karne. Gösterge ve ağırlıklar Karne Gösterge Kataloğundan (CEO onayı 19.10.2026).
CREATE TABLE karne_gosterge (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), rol_adi text NOT NULL, gosterge text NOT NULL, hesap text NOT NULL, veri_kaynagi text NOT NULL, hedef text NOT NULL, agirlik numeric(5,2) NOT NULL CHECK (agirlik >= 0), sira integer NOT NULL, UNIQUE (rol_adi, gosterge)
);
CREATE TABLE personel_karne_donem (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), personel_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), donem text NOT NULL CHECK (donem ~ '^[0-9]{4}-[0-9]{2}$'), rol_adi text NOT NULL, sistem_puani numeric(5,2), yonetici_puani numeric(5,2) CHECK (yonetici_puani BETWEEN 0 AND 100), yonetici_gerekce text, yonetici_ref text REFERENCES kullanici_hesabi (kimlik), nihai_puan numeric(5,2), durum text NOT NULL DEFAULT 'Açık' CHECK (durum IN ('Açık', 'Kapalı')), kapanis_zamani timestamptz, UNIQUE (personel_ref, donem)
);
CREATE TABLE personel_karne_satir (
  donem_ref uuid NOT NULL REFERENCES personel_karne_donem (kimlik), gosterge_ref uuid NOT NULL REFERENCES karne_gosterge (kimlik), agirlik numeric(5,2) NOT NULL, pay numeric(12,2), payda numeric(12,2), deger numeric(7,2), puan numeric(5,2), PRIMARY KEY (donem_ref, gosterge_ref)
);
CREATE TABLE karne_donem_kapanis (donem text PRIMARY KEY, kapatan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE personel_karne_itiraz (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), donem_ref uuid NOT NULL REFERENCES personel_karne_donem (kimlik), itiraz_eden_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), konu text NOT NULL CHECK (length(trim(konu)) > 0), makam_rol_ref text NOT NULL REFERENCES rol (kimlik), durum text NOT NULL DEFAULT 'İncelemede' CHECK (durum IN ('İncelemede', 'Kabul', 'Kısmi Kabul', 'Ret')), onceki_puan numeric(5,2), karar_gerekce text, karar_ref text REFERENCES kullanici_hesabi (kimlik), karar_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX personel_karne_itiraz_tek ON personel_karne_itiraz (donem_ref) WHERE durum = 'İncelemede';
CREATE TABLE karne_agirlik_onerisi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), rol_adi text NOT NULL, degerler jsonb NOT NULL, gerekce text NOT NULL, durum text NOT NULL DEFAULT 'Onayda' CHECK (durum IN ('Onayda', 'Yürürlükte', 'Reddedildi')), oneren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, UPDATE ON karne_gosterge TO yatonet_uygulama;
GRANT SELECT, INSERT, UPDATE ON personel_karne_donem, personel_karne_satir, karne_donem_kapanis, personel_karne_itiraz, karne_agirlik_onerisi TO yatonet_uygulama;

