INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO','Onay süresi uyumu','CEO''ya arz edilip kademe bekleme süresi içinde sonuçlandırılan onay sayısı / CEO''ya arz edilen onay sayısı × 100 (Kritik 30 dk, Yüksek 2 s, Normal 4 s, Planlı 1 iş günü)','Onay modülü – onay silsilesi zaman damgaları','≥ %95',20.0,1);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO','Yönetim kararı kapanış oranı','TPL-03/04/05 kararlarından vadesinde kapatılan eylem sayısı / vadesi gelen eylem sayısı × 100','Toplantılar modülü – karar ve eylem kayıtları','≥ %90',20.0,2);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO','Şirket teklif dönüşüm oranı','Dönemde onaylanan teklif sayısı / sunulan teklif sayısı × 100 (üç aylık ortalama ayrıca hesaplanır)','Fiyat Teklifi modülü – teklif statüleri','≥ %70; üç aylık ortalama %60 altı uyarı (Cilt VI §9.2)',15.0,3);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO','Sigorta tahsilat süresi uyumu','Fatura tarihinden itibaren 30 gün içinde tahsil edilen sigorta faturası tutarı / vadesi gelen sigorta faturası tutarı × 100','Fatura ve Tahsilat modülü – FR-TIC-010','≥ %95',15.0,4);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO','Kritik dosya ilk yanıt uyumu','30 dakika içinde yetkili ilk yanıt verilen Kritik dosya sayısı / Kritik dosya sayısı × 100','İhbar ve Dosya modülü – FR-OPS-009 zaman damgaları','≥ %95',15.0,5);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO','İlk seferde kabul oranı (şirket)','İlk kontrolde düzeltmesiz kabul edilen iş paketi sayısı / kabul edilen iş paketi sayısı × 100','Kalite, Test ve Kabul modülü – FR-KLT-009','≥ %90 (başlangıç hedefi, ilk 180 gün verisiyle güncellenir)',15.0,6);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO Asistanı','Toplantı düzenleme uyumu','Davetleri ve gündem paketi toplantıdan en az 24 saat önce sistemde tamamlanan TPL-03/04/05/10 sayısı / yapılan toplantı sayısı × 100','Toplantılar modülü – davet ve paket zaman damgaları','≥ %95',30.0,7);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO Asistanı','Tutanak kayıt süresi','Kararları toplantıdan sonra 1 iş günü içinde kayda işlenen toplantı sayısı / yapılan toplantı sayısı × 100','Toplantılar modülü – karar kayıt zamanı','≥ %95',30.0,8);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO Asistanı','Yönetim eylemi takip oranı','Vadesi geçen yönetim eylemlerinden vade + 1 iş günü içinde sahibine ve CEO''ya hatırlatma kaydı açılanlar / vadesi geçen yönetim eylemleri × 100','Toplantılar modülü – eylem ve bildirim kayıtları','%100',25.0,9);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('CEO Asistanı','Yazışma aktarım süresi','CEO''ya gelen ve 24 saat içinde YATONET 360 kaydına aktarılan yazışma sayısı / gelen yazışma sayısı × 100','Bildirim ve doküman kayıtları – zaman damgası','≥ %98',15.0,10);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Genel Müdür Yardımcısı','Onay süresi uyumu','GMY''ye arz edilip kademe bekleme süresi içinde sonuçlandırılan onay / GMY''ye arz edilen onay × 100','Onay modülü','≥ %95',25.0,11);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Genel Müdür Yardımcısı','Direktörlük karne ortalaması','Bağlı altı direktörün aylık karne puanlarının aritmetik ortalaması','Akademi ve Karne modülü','≥ 80 / 100',20.0,12);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Genel Müdür Yardımcısı','Bütçe sapması uyumu','Kapanan dosyalardan bitiş maliyeti güncel bütçeye göre ±%5 içinde kalanlar / kapanan dosyalar × 100','İş emri ve bütçe kayıtları, ön muhasebe modülü','≥ %90 (bütçe sapması hedefi ±%5, Cilt VI §9.2)',20.0,13);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Genel Müdür Yardımcısı','Eskalasyon kapanış süresi','GMY''ye taşınan eskalasyonlardan 2 iş günü içinde karara bağlananlar / GMY''ye taşınan eskalasyonlar × 100','Eskalasyon ve görev kayıtları','≥ %90',20.0,14);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Genel Müdür Yardımcısı','Vadesi 30 günü geçen alacak oranı','Vadesi 30 günü geçen alacak tutarı / toplam açık alacak tutarı × 100 (EUR)','Fatura ve Tahsilat modülü – yaşlandırma','≤ %5',15.0,15);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Ticari İşler Direktörü','Teklif dönüşüm oranı','Onaylanan teklif / sunulan teklif × 100 (teknik ret nedenli kayıplar paydadan ayrı raporlanır)','Fiyat Teklifi modülü','≥ %70 (Cilt VI §9.2)',20.0,16);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Ticari İşler Direktörü','Mali kapanış süresi','Teknik bitişten mali kapanışa 10 iş günü içinde geçen dosya / mali kapanışı yapılan dosya × 100','İhbar ve Dosya modülü – Teknik Kapalı ve Kapalı zaman damgaları','≥ %90 (≤10 iş günü; 15 iş günü uyarı)',20.0,17);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Ticari İşler Direktörü','Sigorta tahsilat süresi uyumu','30 gün içinde tahsil edilen sigorta faturası tutarı / vadesi gelen sigorta faturası tutarı × 100','Fatura ve Tahsilat modülü','≥ %95',20.0,18);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Ticari İşler Direktörü','Onay süresi uyumu','TİD''e arz edilip bekleme süresi içinde sonuçlanan onay / TİD''e arz edilen onay × 100','Onay modülü','≥ %95',15.0,19);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Ticari İşler Direktörü','RP-TIC-001 gönderim zamanlılığı','İzleyen ayın ilk 5 iş günü içinde gönderilen sigorta mutabakatı / panelde aktif sigorta şirketi sayısı × 100','Fatura ve Tahsilat modülü – RP-TIC-001 gönderim kaydı','%100',15.0,20);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Ticari İşler Direktörü','Bütçe sapması uyumu','Bitiş maliyeti güncel bütçeye göre ±%5 içinde kalan kapanmış dosya / kapanmış dosya × 100','İş emri ve bütçe kayıtları','≥ %90',10.0,21);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Bilgi Teknolojileri ve Firma Yönetimi Direktörü','Sistem erişilebilirliği','Dönemde planlı bakım dışı kesintisiz geçen süre / toplam süre × 100','Platform olay ve izleme kayıtları','≥ %99,5; Kritik süreçte kesinti ≤24 saat, veri kaybı ≤4 saat',25.0,22);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Bilgi Teknolojileri ve Firma Yönetimi Direktörü','Sürüm kabul zamanlılığı','Planlanan tarihte kabul edilen sürüm / planlanan sürüm × 100','Sürüm ve yayın kayıtları','≥ %90',20.0,23);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Bilgi Teknolojileri ve Firma Yönetimi Direktörü','Alternatif kapasite kapsamı','Doğrulanmış yedek kapasitesi bulunan kritik branş-bölge sayısı / kritik branş-bölge sayısı × 100','Firma Sicili ve Harita modülü','≥ %80 (başlangıç hedefi)',20.0,24);
