INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Bilgi Teknolojileri ve Firma Yönetimi Direktörü','Firma statü kararı süresi','Askı veya çıkarma önerisinden itibaren 5 iş günü içinde karara bağlanan / öneri sayısı × 100','Firma statü karar kayıtları','≥ %90',15.0,26);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Risk ve Kalite Direktörü','İlk seferde kabul oranı','İlk kontrolde düzeltmesiz kabul edilen iş / kabul edilen iş × 100','Kalite, Test ve Kabul modülü','≥ %90 (başlangıç hedefi)',25.0,27);
