INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Risk ve Kalite Direktörü','İş durdurma kapanış uyumu','Doğrulanmış tedbir ve yetkili yeniden başlatma kaydıyla kapanan iş durdurma / iş durdurma × 100','Mobil Saha ve FR-UYG-001 kayıtları','%100',15.0,30);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Risk ve Kalite Direktörü','Yeniden iş oranı','Teknik uygunsuzluk nedeniyle tekrarlanan iş / tamamlanan iş × 100','FR-KLT-008 ve iş emri kayıtları','≤ %5',15.0,31);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Hukuk ve Uyum Direktörü','KVKK başvuru yanıt süresi','Yasal süre (30 gün) içinde karara bağlanan başvuru / sonuçlanan başvuru × 100','KVKK Başvurusu kayıtları','%100',25.0,32);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Hukuk ve Uyum Direktörü','Veri ihlali bildirim süresi','Kurula bildirim gerekli ihlallerden öğrenmeden itibaren 72 saat içinde bildirilen / bildirim gerekli ihlal × 100','FR-HUK-002 kayıtları','%100 (olay yoksa gri)',20.0,33);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Hukuk ve Uyum Direktörü','Hukuki görüş süresi','Talepten itibaren 3 iş günü içinde verilen hukuki görüş / talep edilen görüş × 100','Görev kayıtları – hukuki görüş talepleri','≥ %90 (başlangıç hedefi)',20.0,34);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Hukuk ve Uyum Direktörü','Periyodik gözden geçirme zamanlılığı','Tarihinde tamamlanan mevzuat matrisi, imha ve Resmî Gazete taraması / planlanan × 100','FR-KLT-013 periyodik takvim','%100',20.0,35);
