INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Strateji ve Kurumsal Gelişim Direktörü','Müşteri memnuniyet puanı','Dönemde kapanan dosyaların teslim sonrası geri bildirim puanlarının ortalaması (5 üzerinden)','FR-KLT-011 müşteri memnuniyet puanı alanı','≥ 4,3 / 5 (başlangıç hedefi)',25.0,38);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Strateji ve Kurumsal Gelişim Direktörü','Şikâyet ilk yanıt uyumu','Öncelik sınıfı ilk yanıt süresi içinde yanıtlanan şikâyet / şikâyet × 100','FR-KLT-012 kayıtları','≥ %95',20.0,39);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Strateji ve Kurumsal Gelişim Direktörü','Aktif sigorta şirketi sayısı artışı','Dönem sonu panelde aktif sigorta şirketi sayısı − dönem başı sayı','CRM paydaş kayıtları','Yıllık iş geliştirme planındaki hedef (CEO onayıyla)',15.0,40);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Strateji ve Kurumsal Gelişim Direktörü','Tekrarlayan şikâyet oranı','Tekrarlayan işaretli şikâyet / şikâyet × 100','FR-KLT-012 Tekrarlayan işareti','≤ %10',15.0,41);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Müdürü','Firma ödeme takvimi uyumu','45/120 gün (İB) ve 60 gün (tedarikçi) kuralına göre vadesinde ödenen tutar / vadesi gelen tutar × 100','Ön muhasebe ödeme takvimi, ödeme ve dekont kayıtları','≥ %98',25.0,42);
