INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Müdürü','Tevkifat KDV iade dosyası zamanlılığı','Her ay hazırlanan iade dosyası (1/0) aylık ortalaması × 100','Ön muhasebe – KDV ve tevkifat özeti','%100',10.0,47);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Müdür Yardımcısı','Silsile işlem süresi','Bekleme süresi içinde arz veya iade edilen talep / kademeye gelen talep × 100','Onay modülü','≥ %95',25.0,48);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Müdür Yardımcısı','Cari mutabakat zamanlılığı','Ay kapanışından itibaren 5 iş günü içinde tamamlanan cari mutabakat / mutabakat yapılacak cari × 100','Ön muhasebe modülü','≥ %95',30.0,49);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Müdür Yardımcısı','Banka eşleştirme oranı','Ertesi iş günü sonuna kadar eşleştirilen banka hareketi / banka hareketi × 100','Ön muhasebe – banka hareketleri','≥ %98',25.0,50);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Müdür Yardımcısı','Açık avans yaşı','30 günü aşan açık avans tutarı / toplam açık avans tutarı × 100','FR-TIC-004 ve masraf kayıtları','≤ %5',20.0,51);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Yöneticisi','Silsile işlem süresi','Bekleme süresi içinde arz veya iade edilen talep / kademeye gelen talep × 100','Onay modülü','≥ %95',25.0,52);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Yöneticisi','Proforma süre uyumu (ekip)','Teknik kabulden itibaren 2 iş günü içinde hazırlanan proforma / teknik kabulü yapılan dosya × 100','Fatura ve Tahsilat modülü','≥ %95',25.0,53);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Yöneticisi','Teklif iade oranı','Sonraki kademelerce eksik veya hatalı nedeniyle iade edilen ve kendisinin uygun gördüğü teklif / uygun gördüğü teklif × 100','Onay modülü – iade gerekçeleri','≤ %5',20.0,54);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Yöneticisi','Tahsilat basamağı uyumu','Vadesi geçen alacaklardan takip basamağı gününde işlenen / vadesi geçen alacak × 100','FR-TIC-010 takip basamağı','≥ %95',30.0,55);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Sorumlusu (Ticari Sorumlu)','Teklif hazırlama süresi uyumu','Öncelik sınıfı süresi içinde (Kritik 1, Yüksek 2, Normal 5, Planlı 7 iş günü) sunulan teklif / hazırlanan teklif × 100','Fiyat Teklifi modülü – keşif kapanışı ve gönderim zamanı','≥ %95',25.0,56);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Muhasebe ve Finans Sorumlusu (Ticari Sorumlu)','Proforma süre uyumu','Teknik kabulden itibaren 2 iş günü içinde hazırlanan proforma / teknik kabulü yapılan dosya × 100','Fatura ve Tahsilat modülü','≥ %95',20.0,57);
