INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('İSG Sorumlusu','Ramak kala faaliyet süresi','120 saat içinde faaliyeti atanan ramak kala bildirimi / ramak kala bildirimi × 100','FR-UYG-001, FR-UYG-005','≥ %95',15.0,130);
