INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('İç Denetim Müdürü','Rapor zamanlılığı','Denetim bitiminden itibaren 5 iş günü içinde CEO''ya sunulan rapor / tamamlanan denetim × 100','İç denetim raporları','≥ %95',15.0,135);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('İç Denetçi','Atanmış denetim tamamlama','Takviminde tamamlanan atanmış denetim / atanmış denetim × 100','İç denetim programı','≥ %95',35.0,136);
