INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('İç Denetçi','Taslak rapor süresi','Saha veya kayıt incelemesinin bitiminden itibaren 3 iş günü içinde Müdüre sunulan taslak / tamamlanan denetim × 100','İç denetim raporları','≥ %95',30.0,138);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Müşteri ve Paydaş İlişkileri Müdürü','Şikâyet ilk yanıt uyumu','Öncelik sınıfı ilk yanıt süresinde (Kritik 30 dk, Yüksek 2 s, Normal 4 s, Planlı 1 iş günü) yanıtlanan şikâyet / şikâyet × 100','FR-KLT-012 kayıtları','≥ %95',25.0,139);
