INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Müşteri ve Paydaş İlişkileri Müdürü','Duyuru onay uyumu','Dış kullanıcıya yayımlanan duyurulardan üst kademe onaylı olan / dış kullanıcıya yayımlanan duyuru × 100','Duyurular modülü – FR-OPS-015','%100',15.0,143);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Müşteri ve Paydaş İlişkileri Müdür Yardımcısı','Şikâyet ilk yanıt uyumu','Öncelik sınıfı ilk yanıt süresinde yanıtlanan şikâyet / şikâyet × 100','FR-KLT-012','≥ %95',35.0,144);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Müşteri ve Paydaş İlişkileri Müdür Yardımcısı','Ara bilgilendirme uyumu','Açık şikâyetlerden en az haftada bir ara bilgilendirme kaydı bulunan / açık şikâyet × 100','FR-KLT-012 ve iletişim kayıtları','≥ %95',25.0,145);
