INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik ve Operasyon Direktörü','Direktörlük ilk seferde kabul oranı','Ara/nihai kontrolde düzeltmesiz kabul edilen iş paketleri / kabul edilen iş paketleri; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','FR-KLT-009, FR-KLT-008, FR-KLT-011','≥ %85',20.0,153);
