INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Operasyon Müdürü','Müdürlük hizmet süresi uyumu','Öncelik hedefinde yapılan ilk yanıt, keşif planı, keşiften sonra teklif ve ilerleme raporları / vadesi gelenler; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029); Beklemede süresi düşülür','Dosya modülü zaman damgaları; RP-RAP-001','≥ %90',25.0,159);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Operasyon Müdürü','Beklemede ve uzatma kuralına uyum','10. gün eskalasyonu ve 45. gün kararı zamanında verilen + gerekçeli uzatılan işaretler / vadesi gelen işaretler','Beklemede işareti kayıtları (Ek II §1.7)','%100',15.0,160);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Operasyon Müdürü','Teknik bitişten mali kapanışa süre','Teknik bitişten (FR-KLT-010) mali kapanışa (FR-TIC-007) en çok 10 iş günü içinde kapanan dosyalar / kapanan dosyalar','FR-KLT-010, FR-TIC-007','≥ %90 (15 iş günü uyarı)',15.0,161);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Operasyon Müdürü','Müşteri şikâyet performansı','Şikâyet sayısı / teslim edilen dosya ve kapanış süresinde çözülen şikâyet oranının bileşik puanı','FR-KLT-012','Çözüm ≥ %90; tekrarlayan şikâyet 0',15.0,162);
