INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Operasyon Müdürü','Atama süresi ve kapasite dengesi','Ağırlıklı ortalama: talebin ilk yanıt süresi dolmadan Dosya Sorumlusu ve dosya yöneticisi atanan dosyalar / açılan dosyalar ve %80 uyarısına aynı iş günü aksiyon alınan durumlar / uyarılar; %100 yükte atama 0','Atama zaman damgaları, YATONET 360 atama önerisi, kapasite ekranı','≥ %95',10.0,164);
