INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Operasyon Yöneticisi','Gözetim dosyalarında süre uyumu','Gözetimindeki dosyalarda öncelik hedefinde tamamlanan adımlar / vadesi gelen adımlar; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029); Beklemede süresi düşülür','Dosya modülü zaman damgaları','≥ %90',25.0,172);
