INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Operasyon Yöneticisi','Yönetici nöbeti yanıt süresi','15 dakika içinde dönülen yükselen çağrılar / yükselen çağrılar','Nöbet çağrı kaydı','%100',10.0,177);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Dosya Sorumlusu','Süre uyumu','Öncelik hedefinde tamamlanan adımlar (ilk yanıt, keşif planı, keşiften sonra teklif, ilerleme raporu, kilometre taşları) / vadesi gelen adımlar; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029); Beklemede işareti süresi düşülür','Dosya modülü statü ve zaman damgaları; RP-RAP-001; iş emri kilometre taşları','≥ %90',30.0,178);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Dosya Sorumlusu','Kalite (ilk seferde kabul, uygunsuzluk)','Ağırlıklı ortalama: ilk seferde kabul edilen iş paketleri / kabul edilen paketler ve uygunsuzluk (Minör/Majör/Kritik) sayısı başına düşüm; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','FR-KLT-009, FR-KLT-008, FR-KLT-011','İlk seferde kabul ≥ %85; Kritik uygunsuzluk 0',25.0,179);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Dosya Sorumlusu','Mali sonuç (marj, tahsilat süresi)','Ağırlıklı ortalama: gerçekleşen net marj / %23 hedef ve vadesinde tahsil edilen faturalar / kesilen faturalar (sigortada 30 gün, kurumsal müşteride sözleşme vadesi, bireyselde teslim günü); Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','Dosya bütçe–gerçekleşme, FR-TIC-010, ön muhasebe','Net marj %23; vadesinde tahsilat ≥ %90',20.0,180);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Dosya Sorumlusu','Müşteri ve şikâyet','Ağırlıklı ortalama: dosya kapanış memnuniyet puanı (FR-KLT-011) ve şikâyetsiz kapanan dosya oranı; şikâyette süresinde teyit ve çözüm','FR-KLT-011, FR-KLT-012','Memnuniyet ≥ 4/5; şikâyetsiz dosya ≥ %95',15.0,181);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Dosya Sorumlusu','Kayıt bütünlüğü','Zorunlu formları eksiksiz ve süresinde (WhatsApp aktarımı 24 saat dahil) kapanan dosyalar / kapanan dosyalar','FR-RAP-001, kalite kapıları, denetim izi','≥ %98',10.0,182);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür','Müdürlük ilk seferde kabul oranı','Düzeltmesiz kabul edilen iş paketleri / kabul edilen iş paketleri; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','FR-KLT-009, FR-KLT-008','≥ %85',20.0,183);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür','Garanti ve yeniden işlem oranı','Teknik uygunsuzluk nedeniyle tekrarlanan işler + geçerli garanti bildirimleri / teslim edilen işler; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','FR-KLT-008, FR-KLT-012','≤ %3',20.0,184);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür','Kalite planı zamanında onayı','İş emri serbest bırakılmadan onaylanan FR-KLT-014 ve FR-KLT-015 / iş emri açılan dosyalar','FR-KLT-014, FR-KLT-015, FR-OPS-008 zaman damgaları','%100',15.0,185);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür','Teknik atama ve süre uyumu','Ağırlıklı ortalama: öncelik süresinde yapılan Teknik Uzman ve Teknik Yönetici atamaları ile ertesi iş günü onaylanan nöbet atamaları / gerekenler ve öncelik hedefinde yapılan keşifler / vadesi gelenler; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','Atama zaman damgaları, YATONET 360 atama önerisi, dosya modülü','≥ %90',15.0,186);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür','Zorluk katsayısı disiplini','Teklif onayında katsayısı belirlenen dosyalar / onaylanan teklifler','FR-TIC-008, dosya ana verisi','%100',10.0,187);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür','Saha Sorumlusu zorunlu atama uyumu','Zorunlu koşulu (Kritik öncelik, sıcak iş/kapalı alan/kaldırma, çok firmalı saha, karaya alma, 5.000,00 EUR üzeri bedel) taşıyıp Saha Sorumlusu atanan dosyalar / zorunlu koşullu dosyalar','Atama kaydı, iş emri','%100',10.0,188);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür','Periyodik teknik gözden geçirmeler','Zamanında FR-KLT-013 ile kapatılan muadil liste ve teknik gözden geçirmeler / vadesi gelenler','Periyodik iş takvimi, FR-KLT-013','%100',10.0,189);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür Yardımcısı','Müdürlük teknik rapor süresi','Keşiften sonra 2 iş günü içinde onaya sunulan RP-RAP-002 / yapılan keşifler; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','RP-RAP-002 ve keşif zaman damgaları','≥ %90',20.0,190);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür Yardımcısı','Müdürlük teknik rapor ilk seferde kabul','Teknik Yönetici kontrolü ve Teknik Müdür onayında revizyonsuz kabul edilen raporlar / sunulan raporlar; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','RP-RAP-002 sürüm geçmişi','≥ %85',20.0,191);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür Yardımcısı','Kademe onay süresi uyumu','Kademe bekleme süresi içinde arz/iade edilen talepler / gelen talepler','Onay silsilesi zaman damgaları','≥ %95',15.0,192);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür Yardımcısı','Kritik kontrol tamlığı','Zamanında ve kanıtlı kapatılan kritik kontrol noktaları / planlanan kritik noktalar (atlanan bekletme noktası 0)','FR-KLT-002, FR-KLT-001 (ITP)','≥ %98',15.0,193);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür Yardımcısı','Yönetici nöbeti yanıt süresi','15 dakika içinde dönülen yükselen çağrılar / yükselen çağrılar','Nöbet çağrı kaydı','%100',15.0,194);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Müdür Yardımcısı','Teknik personel yetkinlik güncelliği','Eğitim ve belgesi geçerli Teknik Uzman ve Saha Sorumlusu / toplam; süresi dolmuş belgeyle görevlendirme 0','Akademi kayıtları, atama kaydı','%100',15.0,195);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Yönetici','Keşif ve kapsam onay süresi','Kademe bekleme süresinde sonuçlandırılan RP-RAP-002 kontrolleri ve FR-ONR-012 onayları / gelenler','Onay zaman damgaları','≥ %95',20.0,196);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Yönetici','Gözetim dosyalarında teknik rapor süresi','Keşiften sonra 2 iş günü içinde onaya sunulan RP-RAP-002 / gözetim dosyalarındaki keşifler; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','RP-RAP-002 ve keşif zaman damgaları','≥ %90',15.0,197);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Yönetici','TPL-06 uygulama oranı','Teklif öncesi TPL-06 kaydı bulunan dosyalar / teklif sunulan dosyalar','Toplantı kayıtları, FR-TIC-008','%100',10.0,198);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Yönetici','Gözetim dosyalarında ilk seferde kabul','Düzeltmesiz kabul edilen iş paketleri / kabul edilen paketler; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','FR-KLT-009, FR-KLT-008','≥ %85',20.0,199);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Yönetici','Gözetim dosyalarında onay sonrası ilave iş oranı','Onay sonrası açılan ilave iş bedeli / onaylı teklif bedeli (müşteri tercihi kaynaklı ilave işler hariç); Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','FR-UYG-003, FR-OPS-007','≤ %10',15.0,200);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Yönetici','Kritik kontrol tamlığı','Zamanında ve kanıtlı kapatılan kritik kontrol noktaları / planlanan kritik noktalar (atlanan bekletme noktası 0)','FR-KLT-001, FR-KLT-002','≥ %98',10.0,201);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Yönetici','Saha Sorumlusu ihtiyaç bildirimi','Zorunlu koşul oluştuğu gün Teknik Müdüre bildirilen Saha Sorumlusu ihtiyaçları / zorunlu koşullu gözetim dosyaları','Bildirim kaydı, iş emri bedeli, risk işaretleri','%100',10.0,202);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Uzman','Keşif raporu süresi','Keşiften sonra 2 iş günü içinde onaya sunulan RP-RAP-002 / yapılan keşifler; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','RP-RAP-002 ve keşif zaman damgaları','≥ %90',25.0,203);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Uzman','Teknik rapor ilk seferde kabul','Teknik Yönetici kontrolü ve Teknik Müdür onayında revizyonsuz kabul edilen RP-RAP-002 ile Teknik Yönetici onayında revizyonsuz kabul edilen FR-ONR-012 / sunulanlar; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','RP-RAP-002, FR-ONR-012 sürüm geçmişi','≥ %85',20.0,204);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Uzman','Onay sonrası ilave iş oranı','Onay sonrası FR-UYG-003 ile açılan ilave iş bedeli / onaylı teklif bedeli; müşteri tercihi kaynaklı ilave işler ile keşif raporunda önceden işaretlenmiş erişilemeyen alan/gizli hasar riskinden doğanlar hariç; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','FR-UYG-003, FR-OPS-007, RP-RAP-002','≤ %10',20.0,205);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Uzman','Garanti ve yeniden işlem oranı','Teknik uygunsuzluk nedeniyle tekrarlanan işler + geçerli garanti bildirimleri / uzmanın serbest bıraktığı veya kabul ettiği işler; Σ(k×…)/Σk; k = dosya zorluk katsayısı 0,8–2,0 (Cilt I ¶2029)','FR-KLT-008, FR-KLT-012','≤ %3',20.0,206);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Teknik Uzman','Kayıt bütünlüğü','Zorunlu teknik kayıtları (KL-TEK, FR-TEK-001/002, test formları, fotoğraf bağı) eksiksiz ve süresinde olan dosyalar / atandığı dosyalar','Kalite kapıları, FR-RAP-001, denetim izi','≥ %98',15.0,207);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Saha Sorumlusu','Saha günlüğü kapanışı','Gün sonunda kapatılan saha günlükleri / sahada iş olan günler','Saha günlüğü zaman damgaları','≥ %98',20.0,208);
