INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Saha Sorumlusu','Hakediş doğrulama süresi','Firma ilerleme bildiriminden itibaren 2 iş günü içinde doğrulanan hakedişler / bildirimler','FR-TIC-003 zaman damgaları','≥ %95 (hedef öneri)',15.0,212);
