INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Yönetimi Müdürü','Periyodik tedarik gözden geçirmeleri','Zamanında FR-KLT-013 ile kapatılan muadil liste ve aylık tedarik raporları / vadesi gelenler','Periyodik iş takvimi','%100',10.0,220);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Müdür Yardımcısı','Kademe onay süresi uyumu','Kademe bekleme süresi içinde arz/iade edilen sipariş onayları / gelen onaylar','Onay silsilesi zaman damgaları','≥ %95',20.0,221);
