INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Yöneticisi','Ekip zamanında teslim oranı','Ekibin ihtiyaç tarihinde teslim ettirdiği kalemler / teslim tarihi gelen kalemler','FR-MLZ-002, FR-MLZ-003','≥ %90',25.0,228);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Yöneticisi','Seçim gerekçesi tamlığı','Karşılaştırılabilir teklif veya gerekçeli tek kaynak kaydı bulunan siparişler / siparişler','Tedarik modülü seçim kaydı','%100',20.0,229);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Yöneticisi','Talep bölme ve sipariş revizyon disiplini','Eşik altına bölünmüş sipariş tespiti 0 ve revizyonların izlenebilir kaydı / revizyonlar','Sipariş revizyon geçmişi, iç denetim örneklemi','%100',15.0,230);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Sorumlusu','Talepten siparişe süre','Teknik şartı tam talebin alınmasından siparişin onaya arzına kadar Kritik/Yüksek öncelikte 1 iş günü, diğerlerinde 3 iş günü içinde kalan talepler / talepler','FR-MLZ-001, FR-MLZ-002 zaman damgaları','≥ %90 (hedef öneri)',20.0,231);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Sorumlusu','Tedarikçi sipariş kabul takibi','2 iş günü içinde kabulü alınan siparişler / verilen siparişler','Tedarikçi portalı sipariş kabul kaydı','≥ %95',15.0,232);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Sorumlusu','Zamanında teslim oranı','İhtiyaç tarihinde veya öncesinde teslim edilen kalemler / teslim tarihi gelen kalemler','FR-MLZ-002, FR-MLZ-003','≥ %90',25.0,233);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Sorumlusu','İzlenebilirlik ve belge tamlığı','Seri/parti, sertifika ve dosya bağı tam olan teslim kalemleri / teslim kalemleri (K3–K4''te %100)','FR-MLZ-003, FR-MLZ-004, FR-MLZ-007','≥ %98',20.0,234);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Sorumlusu','Üçlü eşleştirme doğruluğu','Sipariş–teslim–fatura eşleşmesi hatasız iletilen tedarikçi faturaları / iletilen faturalar','FR-TIC-003, ön muhasebe tedarikçi cari','≥ %98',10.0,235);
INSERT INTO karne_gosterge (rol_adi, gosterge, hesap, veri_kaynagi, hedef, agirlik, sira) VALUES ('Tedarik Sorumlusu','Seçim gerekçesi tamlığı','Karşılaştırılabilir teklif veya gerekçeli tek kaynak kaydı olan siparişler / siparişler','Tedarik modülü seçim kaydı','%100',10.0,236);
